// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAgentSpaces List the agent spaces a client may name
	// (GET /agent-spaces)
	ListAgentSpaces(w http.ResponseWriter, r *http.Request)
	// ListCronJobs List configured scheduled jobs
	// (GET /cron/jobs)
	ListCronJobs(w http.ResponseWriter, r *http.Request)
	// ListCronRuns List scheduled run history
	// (GET /cron/runs)
	ListCronRuns(w http.ResponseWriter, r *http.Request, params ListCronRunsParams)
	// ListMessages List a session's conversation messages
	// (GET /messages)
	ListMessages(w http.ResponseWriter, r *http.Request, params ListMessagesParams)
	// ListModels List the models discovered from configured connections
	// (GET /models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// GetSession Read one session
	// (GET /session)
	GetSession(w http.ResponseWriter, r *http.Request, params GetSessionParams)
	// ListSessionAgentSpaceDecisions List a session's agent space decisions
	// (GET /session/agent-space-decisions)
	ListSessionAgentSpaceDecisions(w http.ResponseWriter, r *http.Request, params ListSessionAgentSpaceDecisionsParams)
	// ListSessionAgentRuns List the child agent runs this session has started
	// (GET /session/agents)
	ListSessionAgentRuns(w http.ResponseWriter, r *http.Request, params ListSessionAgentRunsParams)
	// GetSessionAgentRun Read one durable child agent run
	// (GET /session/agents/{agentRunId})
	GetSessionAgentRun(w http.ResponseWriter, r *http.Request, agentRunId AgentRunID, params GetSessionAgentRunParams)
	// CancelSessionAgentRun Cancel one child agent run without ending its parent turn
	// (POST /session/agents/{agentRunId}/cancel)
	CancelSessionAgentRun(w http.ResponseWriter, r *http.Request, agentRunId AgentRunID, params CancelSessionAgentRunParams)
	// ListSessionAgentRunCompactions List one child agent run's compaction lineage
	// (GET /session/agents/{agentRunId}/compactions)
	ListSessionAgentRunCompactions(w http.ResponseWriter, r *http.Request, agentRunId AgentRunID, params ListSessionAgentRunCompactionsParams)
	// GetSessionAgentRunCompaction Read one immutable child compaction record
	// (GET /session/agents/{agentRunId}/compactions/{compactionId})
	GetSessionAgentRunCompaction(w http.ResponseWriter, r *http.Request, agentRunId AgentRunID, compactionId CompactionID, params GetSessionAgentRunCompactionParams)
	// ListSessionAgentRunEvents Follow what one child agent run is doing
	// (GET /session/agents/{agentRunId}/events)
	ListSessionAgentRunEvents(w http.ResponseWriter, r *http.Request, agentRunId AgentRunID, params ListSessionAgentRunEventsParams)
	// ListSessionAgentRunMessages List one child agent run's own durable transcript
	// (GET /session/agents/{agentRunId}/messages)
	ListSessionAgentRunMessages(w http.ResponseWriter, r *http.Request, agentRunId AgentRunID, params ListSessionAgentRunMessagesParams)
	// CancelSession Stop the session's running work
	// (POST /session/cancel)
	CancelSession(w http.ResponseWriter, r *http.Request, params CancelSessionParams)
	// ListSessionCompactions List durable compaction records
	// (GET /session/compactions)
	ListSessionCompactions(w http.ResponseWriter, r *http.Request, params ListSessionCompactionsParams)
	// GetSessionCompaction Read one durable compaction record
	// (GET /session/compactions/{compactionId})
	GetSessionCompaction(w http.ResponseWriter, r *http.Request, compactionId CompactionID, params GetSessionCompactionParams)
	// GetSessionContextSnapshot Read a context snapshot referenced by this session
	// (GET /session/context-snapshots/{contextHash})
	GetSessionContextSnapshot(w http.ResponseWriter, r *http.Request, contextHash ContextHash, params GetSessionContextSnapshotParams)
	// ListSessionEvents List stored protocol events
	// (GET /session/events)
	ListSessionEvents(w http.ResponseWriter, r *http.Request, params ListSessionEventsParams)
	// ListSessionFeed Replay a session's live feed from a sequence
	// (GET /session/feed)
	ListSessionFeed(w http.ResponseWriter, r *http.Request, params ListSessionFeedParams)
	// DeleteWorkspaceFile Delete a file or empty workspace directory
	// (DELETE /session/files)
	DeleteWorkspaceFile(w http.ResponseWriter, r *http.Request, params DeleteWorkspaceFileParams)
	// ListWorkspaceFiles List a workspace directory or inspect a file
	// (GET /session/files)
	ListWorkspaceFiles(w http.ResponseWriter, r *http.Request, params ListWorkspaceFilesParams)
	// ReadWorkspaceFile Read a workspace file as base64
	// (GET /session/files/content)
	ReadWorkspaceFile(w http.ResponseWriter, r *http.Request, params ReadWorkspaceFileParams)
	// WriteWorkspaceFile Write a workspace file atomically
	// (PUT /session/files/content)
	WriteWorkspaceFile(w http.ResponseWriter, r *http.Request, params WriteWorkspaceFileParams)
	// ListSessionJobs List the commands this session has started
	// (GET /session/jobs)
	ListSessionJobs(w http.ResponseWriter, r *http.Request, params ListSessionJobsParams)
	// ReadSessionJobOutput Read a bounded window of one job's output
	// (GET /session/jobs/{jobId}/output)
	ReadSessionJobOutput(w http.ResponseWriter, r *http.Request, jobId JobID, params ReadSessionJobOutputParams)
	// SignalSessionJob Stop one running job
	// (POST /session/jobs/{jobId}/signal)
	SignalSessionJob(w http.ResponseWriter, r *http.Request, jobId JobID, params SignalSessionJobParams)
	// ListSessionJobSignalRequests List the durable signal-request history for one job
	// (GET /session/jobs/{jobId}/signals)
	ListSessionJobSignalRequests(w http.ResponseWriter, r *http.Request, jobId JobID, params ListSessionJobSignalRequestsParams)
	// ListSessionLearnedFiles List the learned rules and skills this session loads
	// (GET /session/learned)
	ListSessionLearnedFiles(w http.ResponseWriter, r *http.Request, params ListSessionLearnedFilesParams)
	// DeleteSessionLearnedFile Delete one learned rule or skill
	// (DELETE /session/learned/file)
	DeleteSessionLearnedFile(w http.ResponseWriter, r *http.Request, params DeleteSessionLearnedFileParams)
	// GetSessionLearnedFile Read one learned rule or skill
	// (GET /session/learned/file)
	GetSessionLearnedFile(w http.ResponseWriter, r *http.Request, params GetSessionLearnedFileParams)
	// GetSessionMCPStatus Report the session's MCP servers
	// (GET /session/mcp)
	GetSessionMCPStatus(w http.ResponseWriter, r *http.Request, params GetSessionMCPStatusParams)
	// ListSessionModelRuns List complete durable model invocations
	// (GET /session/model-runs)
	ListSessionModelRuns(w http.ResponseWriter, r *http.Request, params ListSessionModelRunsParams)
	// ListSessionModelRunCalls Read every provider round for one model invocation
	// (GET /session/model-runs/{modelRunId}/calls)
	ListSessionModelRunCalls(w http.ResponseWriter, r *http.Request, modelRunId ModelRunID, params ListSessionModelRunCallsParams)
	// ListSessionNotices List a session's notices
	// (GET /session/notices)
	ListSessionNotices(w http.ResponseWriter, r *http.Request, params ListSessionNoticesParams)
	// PublishSessionNotice Report a notice to a session
	// (POST /session/notices)
	PublishSessionNotice(w http.ResponseWriter, r *http.Request, params PublishSessionNoticeParams)
	// GetSessionPromptSnapshot Read a prompt snapshot referenced by this session
	// (GET /session/prompt-snapshots/{promptHash})
	GetSessionPromptSnapshot(w http.ResponseWriter, r *http.Request, promptHash PromptHash, params GetSessionPromptSnapshotParams)
	// ReconfigureSession Move a workspace's sessions to another agent space
	// (POST /session/reconfigure)
	ReconfigureSession(w http.ResponseWriter, r *http.Request, params ReconfigureSessionParams)
	// ListSessionTurns List durable turns
	// (GET /session/turns)
	ListSessionTurns(w http.ResponseWriter, r *http.Request, params ListSessionTurnsParams)
	// ListSessionWorkers List a session's worker generations
	// (GET /session/workers)
	ListSessionWorkers(w http.ResponseWriter, r *http.Request, params ListSessionWorkersParams)
	// ListSessions List every session
	// (GET /sessions)
	ListSessions(w http.ResponseWriter, r *http.Request, params ListSessionsParams)
	// OpenSession Open or resume the session for a workspace
	// (POST /sessions/open)
	OpenSession(w http.ResponseWriter, r *http.Request)
	// OpenSystemSession Open or resume the system session
	// (POST /sessions/system)
	OpenSystemSession(w http.ResponseWriter, r *http.Request)
	// ListWorkspaceRoots List the workspace roots this controller may open
	// (GET /workspace-roots)
	ListWorkspaceRoots(w http.ResponseWriter, r *http.Request)
}

